(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["af"] = {"ui":{"skip":"Spring na die inhoud","back":"← Terug na AI-gile","lang.button":"Taal: {name}","lang.dialog":"Kies 'n taal","lang.search":"Soek tale","lang.none":"Geen taal pas nie","lang.notYet":"{name} is nog nie vertaal nie","theme.aria":"Wissel tema: lig, donker of swart","theme.toLight":"Wissel na lig tema","theme.toDark":"Wissel na donker tema","theme.toBlack":"Wissel na swart tema (ware swart, sag op OLED-skerms)","words.underline":"Onderstreep hierdie woorde op die bladsy","words.underlineHelp":"Beweeg oor of tik op 'n gestippelde woord om te sien wat dit beteken.","index.title":"AI-gile: jou KI-ontwikkelaarspan, op een bord","index.description":"AI-gile is 'n kanban-bord vir KI-programmeerspanne. Hulle werk terwyl jy slaap; jy kry een kort hopie dinge om te besluit, te toets en te aanvaar.","hero.logoAlt":"AI-gile-bordikoon","hero.h1.html":"Jou KI-ontwikkelaarspan, op een&nbsp;bord.","hero.alpha":"🐣 Geslote pre-alfa","hero.alphaTitle":"Vroeg en onafgehandel: dankie dat jy dit probeer!","hero.lede":"Hulle bou terwyl jy slaap. Jy word wakker met een kort hopie: 'n paar vrae, 'n paar goed om te toets, een of twee pers diamante. Klik, aanvaar, terug na jou koffie.","dl.windows":"Windows-app","dl.browser":"Gebruik dit in jou blaaier","dl.messenger":"📱 Messenger vir jou foon","dl.soon":"Binnekort","dl.notify":"🔔 Laat weet my wanneer dit oopgaan","dl.notifySmall":"Alfa of beta","hero.secondary":"Agile, maar die span hoef nooit 'n stand-up-koffie te drink nie. (Hulle hou tog stand-ups.)","pitch.h2":"AI-gile in soveel woorde as jy wil","pitch.lede":"Kies 'n lengte, van een woord tot 144. Elke lengte is sy eie beskrywing, vir daardie grootte geskryf. Sleep die skuifbalk of gebruik die pyltjiesleutels.","pitch.rangeLabel":"Lengte in woorde","pitch.dice":"🎲 nog 'n weergawe","pitch.words.one":"{n} woord","pitch.words.other":"{n} woorde","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakters","count.line.html.one":"{n} kaart op die bord op die oomblik","count.line.html.other":"{n} kaarte op die bord op die oomblik","people.humans.html.one":"👥 {n} mens","people.humans.html.other":"👥 {n} mense","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agente","people.working.html.one":"⚡ {n} aan die werk op die oomblik","people.working.html.other":"⚡ {n} aan die werk op die oomblik","pre.title":"AI-gile: hier word iets gebou","pre.description":"Hier word iets gebou. 'n Bord waar KI-spanne bou wat jy vra, en jou leer terwyl hulle werk. Vir nou 'n geslote pre-alfa met vriende.","pre.h1":"Hier word iets gebou. 🤫","pre.line":"'n Bord waar KI-spanne bou wat jy vra, en jou leer terwyl hulle werk. Vir nou 'n geslote pre-alfa met vriende.","pre.btn":"🔔 Laat weet my wanneer dit oopgaan","pre.peek":"Agter die glas: die regte bord, regstreeks. Elke kaart is 'n gekleurde strook.","pre.peekFake":"Agter die glas: so lyk 'n bord wat aan die werk is.","features.aria":"Wat dit doen","f.pile.h":"Een hopie vir jou","f.pile.html":"<b>Vir jou</b> hou alles wat op jou wag, oor elke projek heen: vrae, goed om te toets, take wat net 'n mens kan doen. Jou tou sê wat volgende is en hoe lank dit neem.","f.sleep.h":"Spanne wat werk terwyl jy slaap","f.sleep.p":"Elke projek het 'n leier en 'n span KI-agente. Lewer kommentaar op 'n kaart en die span word wakker, doen die werk, en gee dit terug met stappe wat 'n moeë mens kan volg.","f.tester.h":"'n KI-toetser kyk eerste","f.tester.p":"Voordat enigiets by jou uitkom, volg 'n toetser die stappe in 'n kopie van die app en wys wat hy gesien het, met 'n skermkiekie. Blaai deur die geslaagdes en aanvaar met een klik.","f.proof.h":"Bewys, nie beloftes nie","f.proof.p":"Elke oorhandiging wys wat verander het: die lêers, die diff, die skermkiekies. Jy hoef nie elke app oop te maak om te sien of dit klaar is nie.","f.chat.h":"Gesels met jou leiers","f.chat.p":"'n Discord-agtige balk: een ikoon per projek, pers diamante vir wat jou nodig het. Stuur 'n leier 'n idee; hy maak dit kaarte en 'n plan, met 'n ✅ Gaan-knoppie.","f.tidy.h":"Hou homself netjies","f.tidy.p":"Verwante kaarte word een, deurmekaar titels word reggemaak, en 'n token-kontrole hou die kode skraal. Minder om tussen te wissel, minder om aan te dink.","f.private.h":"Joune, op jou rekenaar","f.private.li1":"Die bord loop op jou eie masjien en antwoord net vir jou.","f.private.li2":"Private DM's tussen mense is end-tot-end-geënkripteer.","f.private.li3":"Geen rekeninge, geen snuffelaars, geen koekies.","f.lang.h":"In jou taal","f.lang.p":"Meer as 120 tale, van Nederlands, Wallies en Japannees tot seerower, Yoda en Klingon, met 'n vinnige wissel terug na Engels vir die vakjargon.","f.service.h":"Van 'n idee tot 'n regte diens","f.service.p":"Iets met KI gebou wat mense nou gebruik? Merk dit as 'n diens en die bord help jou om dit goed te bedryf: beskikbaarheidskontroles, 'n openbare statusbladsy, voorvalle met 'n nabetragting, veranderings wat 'n Go nodig het, rugsteune wat daagliks nagegaan word. Hulp leer jou elke stap soos jy aangaan.","msgr.h2":"AI-gile Messenger: jou span in jou sak","msgr.p1":"Praat met jou KI-span sonder om die bord oop te maak. Klets met jou projekleiers en jou vriende, en sien 'n kaart se toetsstappe en beantwoord hulle, alles van jou foon af.","msgr.p2":"Om dit te koppel, skandeer 'n QR-kode op jou bord. Eerste keer? 'n Vriendelike demo-klets wys jou die pad.","msgr.when":"Eers Android, dan 'n webweergawe vir fone en iPhone.","msgr.who":"Jou projekleier","msgr.b1":"Die regstelling vir donkermodus is gereed. Wil jy die toetsstappe hê?","msgr.b2":"Ja asseblief!","msgr.b3":"1. Maak Instellings oop. 2. Kies Donker. Lyk dit reg?","tl.aria":"Tydlyn van die eerste gesprek tot die padkaart","tl.h2":"Van die eerste gesels tot wat volgende kom","tl.lede":"Regte datums en tye, in jou eie tydsone. Ná vandag is dit die plan, sonder beloofde datums.","tl.today":"Vandag","tl.planned":"beplan","tl.doing":"besig","tl.cards.one":"{n} kaart","tl.cards.other":"{n} kaarte","join.h2":"Doen saam","join.lede":"AI-gile word gebou deur 'n bebaarde eksentrieke ou met AuDHD en 'n paar geestesgesondheidstryde, en 'n groot klomp geduldige agente. Dit is vir eers privaat, in 'n geslote alfa met vriende. Wil jy 'n kans hê wanneer dit oopgaan?","join.btn":"Teken belangstelling in","join.small":"Ons stuur jou 'n e-pos, niks anders nie","footer.tag":"AI-gile. Geen snuffelaars, geen koekies, geen stand-up-koffie.","footer.licence":"Besigheidslisensie","footer.status":"Status","footer.privacy":"Wat ons hou","footer.thanks":"Oproepe danksy ChilledChat","form.sending":"Stuur tans…","form.failed":"Dit het nie gewerk nie: probeer later weer.","form.offline":"Kon nie AI-gile bereik nie: probeer later weer.","form.keep":"Ons gebruik dit net om jou te antwoord, en vee dit dan uit. Geen snuffelaars, geen koekies.","form.keepLink":"Wat ons hou","interest.title":"AI-gile: laat weet my wanneer die alfa oopgaan","interest.description":"Los jou e-pos om te hoor wanneer AI-gile se geslote alfa of beta oopgaan.","interest.h1":"🔔 Laat weet my wanneer dit oopgaan","interest.lede":"AI-gile is in geslote pre-alfa. Los jou e-pos en ons skryf een keer, wanneer daar 'n plek vir jou is.","interest.email":"Jou e-pos","interest.which":"Watter toets?","interest.alpha":"Geslote alfa: vroeg, rof, baie veranderinge","interest.beta":"Beta: bestendiger, later","interest.both":"Enige een, wat ook al eerste kom","interest.submit":"Sit my op die lys","interest.thanks":"Dankie! Jy is op die lys.","licence.title":"AI-gile: besigheidslisensie","licence.description":"Gebruik jy AI-gile in jou besigheid? Doen aansoek om 'n gratis besigheidslisensie.","licence.h1":"📜 Besigheidslisensie","licence.lede":"Gebruik jy AI-gile by die werk? Vertel ons wie jy is en wat jy doen. As dit 'n bietjie goed doen, is die lisensie gratis.","licence.company":"Maatskappy","licence.website":"Webwerf","licence.what":"Wat jy doen","licence.how":"Hoe dit die wêreld help","licence.email":"E-pos","licence.submit":"Doen aansoek","licence.thanks":"Dankie! Ons antwoord per e-pos.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Alles rustig","status.intro":"Werk AI-gile nou? Hierdie bladsy kyk elke 5 minute na die webwerf, borddeling, oproepe en die aflaai.","status.up":"Werk (het in {ms} ms geantwoord)","status.slow":"Het nie op die laaste kontrole geantwoord nie, probeer weer","status.down":"Af: het nie op die laaste twee kontroles geantwoord nie","status.svc.web":"Webwerf","status.svc.web.offers":"Hierdie werf: wat AI-gile is, en die belangstellingsvorm","status.svc.boards":"Borddeling","status.svc.boards.offers":"Openbare borde, boodskappe tussen vriende en uitnodigings","status.svc.calls":"Oproepe","status.svc.calls.offers":"Stem, video en skermdeling in AI-gile","status.svc.download":"Aflaai","status.svc.download.offers":"Die Windows-installeerder en uitnodigingskakels","status.checking":"Kyk tans…","status.offline":"Kan die statusdiens nou nie bereik nie (probeer weer)","status.updated":"opgedateer {ago}","status.justNow":"nou net","status.min":"{n} min gelede","status.hours":"{n} u gelede","status.days":"{n} d gelede","privacy.title":"AI-gile: wat ons hou","privacy.h1":"Wat ons hou","privacy.lede":"Kort weergawe: net wat jy vir ons stuur, en nie vir lank nie.","privacy.only":"Net wat jy vir ons stuur: wat jy in 'n vorm intik, soos jou e-pos. Niks anders oor jou nie.","privacy.sealed":"Dit word verseël sodat ons bediener dit nie kan lees nie: in jou blaaier voordat dit vertrek (op 'n ouer blaaier, die oomblik wat dit aankom). Net ons eie bord kan dit oopmaak.","privacy.server":"Dit word van die bediener uitgevee sodra dit ons bord bereik. Enigiets wat ná 30 dae nog daar is, word in elk geval uitgevee.","privacy.board":"Ons hou dit net op ons bord totdat ons jou geantwoord het, en vee dit dan daar ook uit.","privacy.none":"Geen snuffelaars, geen koekies, geen analitika.","privacy.local":"Jou taal en lig- of donkerkeuse bly in jou eie blaaier. Dit word nooit na ons gestuur nie.","privacy.ask":"Wil jy hê dit moet gouer weg wees? Antwoord op ons e-pos en sê so.","live.h2":"Kyk hoe dit gebou word, regstreeks","live.caption":"Elke kaart is versteek: jy sien die vorm van die werk, nie die woorde nie.","live.watching.one":"regstreeks: {n} kyk","live.watching.other":"regstreeks: {n} kyk","live.last.now":"Laaste kaart pas verskuif","live.last.min.one":"Laaste kaart {n} min gelede verskuif","live.last.min.other":"Laaste kaart {n} min gelede verskuif","live.last.hour.one":"Laaste kaart {n} uur gelede verskuif","live.last.hour.other":"Laaste kaart {n} uur gelede verskuif","live.last.day.one":"Laaste kaart {n} dag gelede verskuif","live.last.day.other":"Laaste kaart {n} dae gelede verskuif","live.offline":"Die lewendige bord haal asem. Kom kyk gou weer.","live.cols":"Backlog|Om te doen|Besig|Span kontroleer|Vir jou om te toets|Vir die span|Klaar"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotte.","Uitbestee."]},{"n":2,"texts":["Robotte-kanban, gratis.","Agente, georganiseer.","Idees, gebou."]},{"n":3,"texts":["Kanban vir robotte.","Idees word funksies.","Gratis agent-kanban."]},{"n":5,"texts":["Kanban-bord wat agente bestuur.","Jy skryf kaarte. Agente bou.","Gratis, plaaslik, getoets, effens simpel."]},{"n":8,"texts":["'n Gratis kanban-bord waar KI-agente werk doen.","Skryf 'n idee. Agente bou dit. Jy aanvaar.","Agile vir een mens en baie geduldige robotte."]},{"n":13,"texts":["'n Kanban-bord op jou rekenaar waar KI-agente die kaarte optel en afhandel.","Skryf 'n idee. 'n Span agente bou dit. 'n Toetser kyk dit na.","Gratis, geen rekeninge, geen snuffelaars: 'n bord, 'n paar robotte, en jy aan die stuur."]},{"n":21,"texts":["AI-gile is 'n kanban-bord om saam met KI-programmeeragente te werk. Hulle tel die kaarte op; jy toets en aanvaar dit.","Elke projek kry 'n leier en 'n span KI-agente. Lewer kommentaar op enige kaart en die span gaan aan die werk.","'n Gratis, persoonlike taakbord wat op jou eie rekenaar loop. Die werkers is robotte. Die een wat ja sê, is jy."]},{"n":34,"texts":["Jy sit idees op 'n bord. 'n Span KI-agente maak daarvan werkende funksies, toets dit, en gee dit terug met stappe om te probeer. Niks tel as klaar totdat jy dit sê nie.","AI-gile is 'n tuisgemaakte kanban-bord wat Rich gebou het met baie hulp van die agente wat dit nou bestuur. Dit is gratis, loop op jou rekenaar, en word met vriende gedeel, nie verkoop nie.","Dink aan 'n gewone kanban-bord, met kolomme van Backlog tot Klaar, behalwe dat KI-agente die kaarte optel. Hulle rapporteer vordering, vra vrae as hulle vassit, en wag altyd vir jou duim in die lug."]},{"n":55,"texts":["AI-gile is 'n kanban-bord waar die span uit KI-agente bestaan. Elke projek het 'n leier wat die werk beplan en helpers wat dit bou. Wanneer 'n funksie gereed is, probeer 'n KI-toetser dit en neem 'n skermkiekie, dan beland dit in jou hopie. Aanvaar dit, of lewer kommentaar en hulle werk dit oor.","Dit het begin as een persoon se manier om baie KI-programmeersessies gelyktydig dop te hou, en het gegroei tot 'n regte bord. Dit loop op jou masjien, vra geen rekening nie, en het geen snuffelaars nie. Dit is gratis vir vriende en enigeen wat nuuskierig is. Dit is ook onafgehandel, so verwag rowwe kante en die af en toe verrassing.","Hier is die eerlike weergawe. Jy moet steeds die idees hê, en jy moet steeds die resultate nagaan. Wat AI-gile doen, is alles tussenin: dit hou die kaarte in orde, wek die regte agent wanneer jy kommentaar lewer, wys presies wat verander het, en hou alles in een kort hopie vir jou."]},{"n":89,"texts":["AI-gile is 'n gratis kanban-bord wat jy op jou eie rekenaar laat loop. In plaas van mense het elke projek 'n span KI-agente: 'n leier wat jou idees in kaarte en 'n plan omskep, en helpers wat die kaarte in volgorde van prioriteit optel. Wanneer iets gebou is, volg 'n KI-toetser die toetsstappe en wys jou wat hy gesien het. Dan wag dit in een hopie gemerk Vir jou. Jy aanvaar dit, of jy lewer kommentaar en die span probeer weer. Niks kom ooit by Klaar uit sonder jou nie.","Party funksies verwag jy dalk nie. 'n Nagwag hou die kolom Om te doen aangevul terwyl jy slaap, en kies kaarte wat nie 'n antwoord van jou nodig het nie. 'n Tokenteller wys hoeveel die agente vandag en hierdie week gebruik het, en Geen-Token-Modus sê vir hulle om op te hou spandeer. Jy kan vriende boodskappe stuur, en private boodskappe is end-tot-end-geënkripteer. Die bord praat sowat 120 tale, onder andere Nederlands, Vlaams, seerower en Klingon. Niks daarvan kos 'n sent nie, en niemand probeer dit ook vir jou verkoop nie.","AI-gile is 'n klein, persoonlike projek, nie 'n maatskappy nie. Rich wou na etlike KI-programmeerprojekte omsien sonder om elke app oop te maak om daarna te kyk, so hy en die agente het 'n bord daarvoor gebou, en toe die bord gebruik om die res van homself te bou. Dit is in geslote pre-alfa, wat beteken dit werk, meestal, vir 'n handjievol vriende. Daar is geen pryslys, geen nuusbrief en geen groeiplan nie. As dit nuttig klink, kan jy vra om dit te probeer wanneer dit 'n bietjie verder oopgaan."]},{"n":144,"texts":["AI-gile is 'n kanban-bord vir een mens en 'n klomp KI-agente. Dit loop op jou eie rekenaar en dit is heeltemal gratis. Jy voeg projekte by, en elke projek kry 'n leier en 'n klein span. Jy gesels met die leier, 'n bietjie soos op Discord, en beskryf 'n idee; die leier maak dit kaarte en 'n plan, en wag dan dat jy Gaan druk. Die span werk die kaarte in volgorde van prioriteit af, met 'n eenvoudige opdragreël wat vir taalmodelle gemaak is. Voordat enigiets na jou terugkom, volg 'n KI-toetser die stappe in 'n kopie van die app en heg 'n skermkiekie aan. Klaargemaakte werk beland in jou hopie met die veranderde lêers en die diff. Jy aanvaar dit, of jy los 'n kommentaar en die span word wakker en probeer weer. Net jy kan 'n kaart na Klaar skuif.","'n Dag met AI-gile, ongeveer. In die aand los jy 'n paar kommentare: hierdie knoppie is op die verkeerde plek, daardie lys moet gesorteer wees, kan ons 'n donker modus kry. Jy gaan slaap. Die agente lees die kommentare, maak die veranderinge, toets dit en gee dit aan jou terug. As Om te doen leegloop, vul die nagwag dit uit die backlog met kaarte wat geen antwoord van jou nodig het nie. In die oggend is daar een kort hopie: 'n paar vrae en 'n paar goed om te probeer, elk met stappe wat 'n slaperige mens kan volg en 'n skermkiekie wat wys dit werk. Jy klik deur, aanvaar die goeies en stuur die res terug. 'n Tokenteller wys wat alles gebruik het, en Geen-Token-Modus is daar vir maer weke. Dan eet jy ontbyt, waarmee die agente nog nie kan help nie.","Eerstens, wat AI-gile nie is nie. Dit is nie 'n begin-maatskappy nie, dit is nie te koop nie, en niemand versamel jou data nie. Dit is 'n gratis bord wat op jou rekenaar loop, sonder rekeninge, snuffelaars of koekies. Wat dit wel is: een netjiese plek om elke KI-programmeerprojek gelyktydig te sien, met 'n span agente wat die kaarte doen en jy wat die besluite neem. Dit voeg verwante kaarte saam, maak deurmekaar titels reg, en hou dop hoe skraal die kode bly. Dit praat sowat 120 tale, van Nederlands en Vlaams tot seerower en Klingon. Vriende kan mekaar boodskappe stuur, privaat en geënkripteer. Dit is gebou deur Rich en 'n groot klomp geduldige agente, meestal deur homself te gebruik. Dit is in geslote pre-alfa, so dit is op plekke rof. As dit na pret klink, vra mooi en jy kan dalk vroeg inkom."]}],"quips":{"1":"Een woord. Gewaagd. Dalk te gewaagd.","3":"Drie woorde. Reeds eerliker as die meeste produkbladsye.","8":"Agt woorde. Steeds korter as 'n stand-up.","21":"Die lengtes is storiepunte, terloops. Natuurlik is hulle.","55":"Vyf-en-vyftig woorde. Twee kaarte is klaar terwyl jy dit gelees het.","144":"Dis die lang een. Daar is geen 233 nie. Die agente is gaan slaap."}},"timeline":{"first-idea.name":"Die eerste idee","first-idea.line":"Die allereerste gesprek, voordat daar enige kode was.","first-board.name":"Eerste bord","first-board.line":"'n Bord wat sy eie bou naspoor: kaarte, kolomme, sleep-en-los, projekte.","team-roles.name":"Span en rolle","team-roles.line":"Agentprofiele, spansjablone, ruimtes en wie wat doen.","install.name":"Installeer en weergawes","install.line":"'n Zip wat 'n vriend kan installeer, selfopdatering, kanale en terugrol.","usage-saver.name":"Gebruiksbespaarder","usage-saver.line":"Meet wat lopies kos, hou die kode skraal, spaar jou limiet.","friends.name":"Vriende en deel","friends.line":"Private DM's, 'n versleutelde relay, uitnodigings, rolle en gedeelde projekte.","languages.name":"Tale","languages.line":"Elke skermteks in 'n taallêer, met Nederlands en Vlaams eerste.","ai-tester.name":"KI-toetser","ai-tester.line":"'n Toetser kyk elke oorhandiging eerste na en wys wat hy gesien het.","website.name":"Die webwerf","website.line":"aigile.lol, die teaser en hierdie tydlyn.","streaming.name":"Klets en stroming","streaming.line":"Discord, Twitch, OBS, stroomermodus, GIF's en emoji's.","no-ai.name":"Sonder-KI-uitgawe","no-ai.line":"'n Bord vir mense wat sonder KI programmeer, en openbare borde.","night-watch.name":"Nagwag","night-watch.line":"'n Wag en Scrum Master hou die spanne op koers terwyl jy slaap.","p-more.name":"Alles anders","p-more.line":"Kleiner idees wat nog op hul beurt wag.","p-android.name":"Foon en Android","p-android.line":"Bereik jou bord vanaf 'n foon, dan 'n eie Android-app.","p-release.name":"Alfa en verder","p-release.line":"Geslote alfa, die lewendige werf, dan beta.","p-languages.name":"Meer tale","p-languages.line":"Meer as honderd tale, en 'n onderdompelingsmodus vir leerders.","p-engines.name":"Meer KI-enjins","p-engines.line":"Kies Claude, Codex of Gemini per agent.","p-pro.name":"Professionele praktyk","p-pro.line":"Risikoetikette, samevoegpoorte, voorvalkaarte en leuningrelings.","p-self.name":"Na jou omsien","p-self.line":"Moeë-modus, selfsorg-herinnerings en 4:20.","p-servers.name":"Bedieners en skaal","p-servers.line":"Globale bedienerinstellings, rolle en beplanning vir groei.","p-livestream.name":"Stroom-ekstras","p-livestream.line":"Twitch-klets, eie emoji's en 'n openbare regstreekse blik."},"words":{"button":"📖 Vakjargon","h":"📖 Woorde verduidelik","intro":"Die woorde wat jy in AI-gile teëkom, in gewone taal: dit bou, dit veilig verander, dit aan die gang hou vir die mense wat dit gebruik, en as 'n span saam met KI werk.","search":"Soek 'n woord…","none":"Geen woord stem daarmee ooreen nie.","close":"Maak toe","count":{"one":"{count} woord","other":"{count} woorde"},"groups":[{"id":"build","name":"🛠️ Dit bou"},{"id":"change","name":"🔀 Dit veilig verander"},{"id":"run","name":"🛎️ 'n Diens bedryf"},{"id":"team","name":"🤝 As 'n span werk (en saam met KI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Die projek se gids met kode en sy volle geskiedenis van commits, gewoonlik ook op GitHub gehou.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"'n Aparte werklyn in die kode, sodat veranderinge gemaak kan word sonder om aan die hoofweergawe te raak.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"'n Gestoorde kiekie van die kode, met 'n kort nota van wat verander het. Jy kan altyd na een teruggaan.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Gestoorde kiekies (commits) van hierdie rekenaar na GitHub stuur, sodat hulle 'n rugsteun het en gedeel word."},{"id":"merge","g":"build","word":"Merge","text":"Die veranderinge van 'n branch weer by die hoofweergawe voeg."},{"id":"pr","g":"build","word":"Pull request","text":"Vra dat 'n branch se veranderinge nagegaan en by die hoofweergawe saamgevoeg word.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Die kode opruim sonder om te verander wat dit doen: kleiner lêers, duideliker name, minder herhaling."},{"id":"bug","g":"build","word":"Bug","text":"Iets wat nie werk soos dit moet nie.","also":["bugs","fout","foute"]},{"id":"test","g":"build","word":"Toets","text":"'n Voltooide stuk werk uitprobeer om seker te maak dit doen wat gevra is, voordat jy dit aanvaar.","also":["toetse","test","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Kort vir quality assurance (gehalteversekering): die outomatiese kontroles wat loop voordat enigiets regstreeks gaan. As QA rooi is, het iets misluk, en dit kan nie regstreeks gaan voordat dit reggemaak is nie.","also":["gehaltebeheer","kwaliteitskontrole","KW"]},{"id":"deploy","g":"change","word":"Deploy","text":"'n Nuwe weergawe aanlyn sit, byvoorbeeld op 'n bediener waar mense dit gebruik."},{"id":"release","g":"change","word":"Vrystelling","text":"'n Benoemde bondel klaar werk wat saam regstreeks gaan, met kort notas oor wat verander het. 🚀 Vrystellings skryf die notas uit die klaar kaarte.","also":["vrystellings","release"]},{"id":"rollback","g":"change","word":"Rol terug","text":"Teruggaan na die laaste weergawe wat gewerk het as 'n nuwe een moeilikheid gee. In AI-gile maak dit 'n kontrolelys van die ontdoen-stappe wat op elke verandering geskryf is.","also":["terugrol","teruggerol","rollback"]},{"id":"live","g":"change","word":"Regstreeks","text":"Die regte weergawe wat mense gebruik, anders as 'n kopie om dinge op uit te probeer. Ontwikkelaars noem dit ook produksie.","also":["produksie","live"],"noTip":1},{"id":"change","g":"change","word":"Verandering","text":"'n Beplande verandering aan iets waarop mense staatmaak, eers neergeskryf: wat, hoekom, die risiko, wanneer, en hoe om dit te ontdoen. Begin een met 🔀 Dien 'n verandering in.","also":["veranderings","veranderingsversoek","change"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Iets wat kan skeefloop, met 'n telling vir hoe waarskynlik en hoe erg dit sou wees. ⚠️ Risiko's hou hulle in een lys, hoogste telling eerste, elk met 'n datum om weer te kyk.","also":["risiko's","risikoregister"]},{"id":"chgwin","g":"change","word":"Veranderingsvenster","text":"Die tye wanneer veranderings regstreeks mag gaan, soos 'n stil Dinsdagaand. Buite 'n venster kan 'n veranderingskaart nie klaargemaak word nie, tensy dit 'n noodgeval is.","also":["veranderingsvensters","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"'n Vinnige stemming net voordat 'n verandering regstreeks gaan: elke persoon wat moet goedkeur, sê Go of No go. Dit gaan net voort as hulle saamstem.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Goedkeuring","text":"Wag vir 'n ja voordat werk begin. 'n Kaart wat 'n vriend indien, of 'n verandering, wag in ✅ Goedkeurings totdat jy dit goedkeur of afkeur.","also":["goedkeurings"]},{"id":"quiettime","g":"change","word":"Stil tyd","text":"'n Tydperk, soos 'n stroom, 'n demo of die nag, wanneer niks regstreeks gaan nie. Die spanne werk en toets verder, maar regstreeks gaan wag totdat dit verby is. Elders word dit 'n veranderingsbevriesing genoem.","also":["stil tye","veranderingsbevriesing","change freeze"]},{"id":"service","g":"run","word":"Diens","text":"Iets wat jy gebou het waarop mense staatmaak, soos 'n webwerf of 'n toep, wat opgepas word sodat dit aanhou werk. Merk “Hierdie projek is 'n diens” en sê wat dit bied, wie dit gebruik en wie op diens is.","also":["dienste"]},{"id":"uptime","g":"run","word":"Beskikbaarheidskontrole","text":"'n Outomatiese kontrole, elke paar minute, dat jou diens nog antwoord. As dit 'n paar keer na mekaar misluk, maak AI-gile self 'n voorvalkaart oop.","also":["beskikbaarheid","uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Statusbladsy","text":"'n Openbare bladsy wat wys of 'n diens werk (groen, oranje of rooi) met die jongste nuus, sodat die mense wat dit gebruik kan kyk in plaas van vra.","also":["statusbladsye","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Where questions and reports from the people using your service come in. AI-gile sorts each one into a request, an incident or an idea, and says so when it looks like something already reported.","also":["service desks","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Service request","text":"Someone asking for something ordinary, like a new account or a bit of help, rather than reporting that something is broken. It waits its turn; an incident goes first.","also":["service requests"]},{"id":"incident","g":"run","word":"Voorval","text":"Iets wat nou stukkend is vir die mense wat dit gebruik, soos die webwerf wat af is. 'n 🔥 Voorvalkaart spring die tou: om dit weer aan die werk te kry kom eerste.","also":["voorvalle","incident"]},{"id":"major","g":"run","word":"Groot voorval","text":"'n Groot voorval: baie mense geraak, of geld of data in gevaar. Een knoppie sit elke span daarop (swerm), maak wakker wie ook al op diens is en vra elke 30 minute vir 'n statusopdatering.","also":["groot voorvalle","major incident"]},{"id":"oncall","g":"run","word":"Op diens","text":"Die een wees wat antwoord as iets breek, selfs in die nag. Elke diens het 'n spanlid op diens wat eerste wakker gemaak word vir sy voorvalle.","also":["diensbeurt","bystand","on call"]},{"id":"replyby","g":"run","word":"Antwoordtyd","text":"Hoe lank 'n kaart mag wag vir 'n eerste antwoord, byvoorbeeld 'n uur vir 'n voorval. Daarna kry dit 'n rooi horlosie, sodat niks stilletjies vergeet word nie. Ook 'n antwoordteiken genoem.","also":["antwoordtye","antwoordteiken","antwoordteikens"]},{"id":"postmortem","g":"run","word":"Nabetragting","text":"'n Kort terugblik na 'n voorval: wat gebeur het, wat gehelp het en wat om te verander, sonder om iemand te blameer. 'n Voorval kan nie sonder een gesluit word nie.","also":["nabetragtings","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Probleem","text":"Die verborge oorsaak agter een of meer voorvalle. 'n 🧩 Probleemkaart groepeer voorvalle wat aanhou terugkom, sodat die oorsaak gevind en vir goed reggemaak word.","also":["probleme"],"noTip":1},{"id":"rootcause","g":"run","word":"Grondoorsaak","text":"Die ware rede waarom iets gebreek het, nie net wat jy sien skeefloop het nie. Maak die grondoorsaak reg en die voorval hou op terugkom.","also":["grondoorsake","root cause"]},{"id":"workaround","g":"run","word":"Tydelike oplossing","text":"'n Manier om dinge aan die werk te hou totdat die regte oplossing gereed is, soos om iets te herbegin as dit vashaak. Dit word op die probleemkaart geskryf sodat niemand dit weer hoef uit te werk nie.","also":["tydelike oplossings","noodoplossing","workaround"]},{"id":"knownerror","g":"run","word":"Bekende fout","text":"'n Probleem waarvan die oorsaak verstaan word en wat 'n tydelike oplossing het, maar nog nie reggemaak is nie. 🧩 Bekende foute lys hulle, sodat almal die tydelike oplossing gebruik in plaas van weer te grawe.","also":["bekende foute","known error"]},{"id":"runbook","g":"run","word":"Draaiboek","text":"Stap-vir-stap-instruksies om 'n bekende soort moeilikheid reg te maak, sodat dit elke keer vinnig op dieselfde manier gedoen word. Na 'n groot voorval kan die span een voorstel wat jy kan goedkeur.","also":["draaiboeke","runbook"]},{"id":"ci","g":"run","word":"Configuration item","text":"One thing your service depends on, like a server, a domain, a certificate, a key or a supplier. 🗂️ Configuration items lists them per service, so you can see what an incident affects and what needs renewing or a backup.","also":["configuration items"]},{"id":"expiry","g":"run","word":"Expiry date","text":"AI-gile keeps an eye on dates like when a certificate or a domain runs out. Within 30 days of the date it makes one card to renew it, so nothing stops working by surprise.","also":["expiry dates","expiry","expiry watch"]},{"id":"backup","g":"run","word":"Rugsteun","text":"'n Gestoorde kopie van jou data van vroeër, om op terug te val as iets verlore raak of beskadig word. AI-gile maak elke dag 'n rugsteun van jou borde.","also":["rugsteune","backup"]},{"id":"restore","g":"run","word":"Herstel","text":"Data uit 'n rugsteun terugsit. 'n Rugsteun tel eers regtig as jy weet dit kan herstel word, so dit is die moeite werd om dit af en toe te probeer.","also":["herstel","teruggesit","restore"]},{"id":"svcreview","g":"run","word":"Service review","text":"A look back at one month of a service: incidents opened and fixed, how quickly people got an answer, uptime and tokens used. The Monthly review shows it for each service.","also":["service reviews","monthly review","monthly reviews"]},{"id":"accessreview","g":"run","word":"Access review","text":"Checking every 90 days who can still get in: share links, friends’ roles and kept secrets. You keep or remove each one, so old access doesn’t linger.","also":["access reviews"]},{"id":"improvements","g":"run","word":"Improvement list","text":"Everything the team decided to get better at, in one place: retro suggestions, review actions and problem fixes, each with its status. Find it under 📈 Improvements.","also":["improvement lists","improvements"]},{"id":"tokencap","g":"run","word":"Token cap","text":"A monthly limit on the tokens a service’s agents may use. At 80% you get a warning; at 100% their background work waits until next month or until you raise the cap.","also":["token caps"]},{"id":"backlog","g":"team","word":"Backlog","text":"Idees en werk wat nog nie ingeskeduleer is nie. Daar word aan niks gewerk voordat dit na Om te doen skuif nie."},{"id":"sprint","g":"team","word":"Sprint","text":"'n Kort tydperk van werk (dikwels 'n week of twee) met 'n ooreengekome stel kaarte om klaar te maak.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"'n Vinnige inskakeling: wat elke spanlid gedoen het, wat hulle volgende doen, en wat hulle terughou.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"'n Bord met kolomme (Om te doen, Besig, Klaar) waar kaarte van links na regs skuif soos werk gebeur."},{"id":"wip","g":"team","word":"WIP-limiet","text":"Work in progress: die hoogste aantal kaarte wat 'n kolom mag hou, sodat die span dinge klaarmaak voor hulle meer begin.","also":["WIP"]},{"id":"dod","g":"team","word":"Definisie van Klaar","text":"Die span se kort kontrolelys van wat “klaar” beteken, soos getoets en verduidelik, voordat 'n kaart aan jou oorhandig word. Sy tweeling, die Definisie van Gereed, sê wanneer 'n kaart duidelik genoeg is om te begin.","also":["Definisie van Gereed","Definition of Done","Definition of Ready"]},{"id":"testpile","g":"team","word":"Toetsstapel","text":"Die klaar kaarte wat wag dat jy hulle probeer, een na die ander. Aanvaar een of stuur dit terug met 'n nota, en die volgende een kom op.","also":["toetsstapels"]},{"id":"retro","g":"team","word":"Terugblik","text":"'n Terugblik op hoe die span werk, om ooreen te kom oor een ding om beter te doen. In AI-gile stel 'n terugblik 'n verandering aan die span se werkswyse voor, en jy sê Gaan of Nog nie.","also":["terugblikke","retro","retrospektief"]},{"id":"peerreview","g":"team","word":"Portuurhersiening","text":"'n Tweede paar oë: 'n ander KI kyk elke kaart se werk na voordat dit by jou uitkom, sodat minder foute deurglip.","also":["kodehersiening","peer review","code review"]},{"id":"swarm","g":"team","word":"Swerm","text":"Alle hande aan dek: elke span los ander werk om op een dringende projek te help totdat dit uitgesorteer is. Ander projekte wag intussen.","also":["swerm","swarm"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Die een wat die werk aan die vloei hou: sien vasgehaakte kaarte raak, por die spanne aan en herinner jou aan wat wag. In AI-gile doen die Lead Scrum Master dit oor elke projek.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"'n KI wat self aan 'n taak werk: lees die kode, maak veranderinge, voer kontroles uit, en rapporteer terug.","also":["agents","agente"]},{"id":"token","g":"team","word":"Token","text":"Die eenheid waarin KI-gebruik getel word: min of meer 'n paar letters teks gelees of geskryf. Minder tokens, meer van jou plan oor.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"'n Klein opdrag wat self op 'n bepaalde oomblik loop, bv. wanneer 'n KI-sessie begin, sodat die span jou kommentaar hoor.","also":["hooks"]}]}};
